import * as PIXI from 'pixi.js';

import { HowToPlaySlide } from './htp-slide';
import { BASE_HEIGHT, BASE_WIDTH, SlideManager, } from './slide-manager';

const TEXT_STYLE: Partial<PIXI.TextStyle> = {
    fontSize: 24,
    fill: '#1DBBAC'
};

export class HowToPlayManager extends SlideManager {
    private title: PIXI.Text;
    private previousSlide!: HowToPlaySlide;

    constructor(slides: HowToPlaySlide[],
        slideControlAssets: { enabled: PIXI.Texture, disabled: PIXI.Texture },
        dimensions: { width: number, height: number },
        countryCode: string = 'en-gb') {
        super(slides, slideControlAssets, dimensions);

        this.title = new PIXI.Text(this.getLocalisedTitle(countryCode), TEXT_STYLE);
        this.title.anchor.set(0.5);

        this.addChildren();

        (this.slides as HowToPlaySlide[]).forEach((slide, index) => {
            const enabled = index === 0;

            if (enabled) {
                slide.play();
            }
        });

        this.handleOrientationChange(dimensions.width, dimensions.height);
    }

    public handleOrientationChange(viewportWidth: number, viewportHeight: number): void {
        const halfViewportWidth = viewportWidth * 0.5;
        const heightScale = viewportHeight / BASE_HEIGHT;
        const widthScale = viewportWidth / BASE_WIDTH;
        const isPortrait = viewportHeight >= viewportWidth;
        const scale = (heightScale > widthScale ? widthScale : heightScale);

        super.handleOrientationChange(viewportWidth, viewportHeight);

        this.slides.forEach((slide) => {
            slide.scale.set(scale);
        });

        this.title.style.fontSize = BASE_HEIGHT * 0.15;
        this.title.scale.set(scale);
        this.title.position.x = halfViewportWidth;
        this.title.position.y = isPortrait ? viewportHeight * 0.4 - (this.title.height * 1.5) : this.title.height * 0.5;
    }

    protected addChildren(): void {
        this.addChild(this.slideMask);

        (this.slides as HowToPlaySlide[]).forEach((slide) => {
            this.addChild(slide);
        });

        this.addChild(this.swipeRegion);
        this.addChild(this.controlsContainer);

        this.addChild(this.title);
    }

    protected transitionSlideLeft(isAutoPlayTransition: boolean = false, goToLastSlide: boolean = false, newSlideIndex?: number): void {
        const currentSlide = (this.slides as HowToPlaySlide[])[this.currentSlideIndex];

        currentSlide.animation.update(0);

        this.previousSlide = currentSlide;
        super.transitionSlideLeft(isAutoPlayTransition, goToLastSlide, newSlideIndex);
    }

    protected transitionSlideRight(isAutoPlayTransition: boolean = false, goToFirstSlide: boolean = false, newSlideIndex?: number): void {
        const currentSlide = (this.slides as HowToPlaySlide[])[this.currentSlideIndex];

        currentSlide.animation.update(0);

        this.previousSlide = currentSlide;
        super.transitionSlideRight(isAutoPlayTransition, goToFirstSlide, newSlideIndex);
    }

    protected onSlideInFinished(): void {
        if (this.slides[this.currentSlideIndex].position.x !== this.slideInPosition) {
            super.transitionSlideIn();
        } else {
            this.previousSlide.animation.state.setEmptyAnimations(0);
            this.previousSlide.animation.skeleton.setToSetupPose();
            (this.slides as HowToPlaySlide[])[this.currentSlideIndex].play();
        }
    }

    private getLocalisedTitle(countryCode: string): string {
        // TODO: Add other translations for the other countries
        switch (countryCode) {
            case 'se-se':
                return 'hur man spelar';
            case 'dk-dk':
                return 'sådan spiller du';
            case 'it-it':
                return 'Come Giocare';
            case 'es-es':
                return 'cómo jugar';
            case 'en-gb':
            default:
                return 'how to play';
        }
    }
}
